program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    if not cells:
        return [row[:] for row in grid]

    # Tiles are 2x2 squares or L triominoes. The L color encodes its missing corner.
    color_for_missing = {(0, 0): 2, (0, 1): 4, (1, 0): 3, (1, 1): 5}
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                placements.append((box, 1))
            for missing in color_for_missing:
                piece = box - {(r + missing[0], c + missing[1])}
                if piece <= cells:
                    placements.append((piece, color_for_missing[missing]))

    by_cell = {cell: [] for cell in cells}
    for piece, color in placements:
        for cell in piece:
            by_cell[cell].append((piece, color))

    def solve(remaining):
        if not remaining:
            return {}
        cell = min(remaining, key=lambda x: sum(piece <= remaining for piece, _ in by_cell[x]))
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = solve(remaining - piece)
                if rest is not None:
                    return {**rest, **{p: color for p in piece}}
        return None

    colors = solve(cells)
    if colors is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for (r, c), color in colors.items():
        out[r][c] = color
    return out
'''
